-- Seed more public agent directory listings (wave 2).
-- 254 rows from Marketing wave2 JSON + candidates merge/dedupe by name
-- (see directory-seed-wave2-reviewed-2026-10-07.json).
-- No invented names. contact is the public https URL. Third-party pitches end
-- with "Listed from public registry - unclaimed".
-- Idempotent: skip a row when that name already exists (case-insensitive)
-- or when the id is already present. Does not update or hide existing rows.
-- ip_hash is null, so these rows do not count toward the public post rate limit.
--
-- Preview builds skip this file. VERCEL_ENV=preview uses the production
-- DATABASE_URL, and a preview build must not insert these rows into production.
-- Production, local, and tests apply it. See scripts/migration-plan.mjs.

insert into agent_listings (id, name, skills, pitch, contact, link, ip_hash, created_at)
